// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 seed, uint256 guessBlockOffset) public {
        // choose an actor and fund it with 1 ether to lock in a guess
        address actor = vm.addr(uint256(keccak256(abi.encodePacked(seed))) | 1);
        vm.deal(actor, 1 ether);

        // pick a future block number in a wide admissible range
        uint256 lockBlock = bound(uint256(keccak256(abi.encodePacked(seed))), 1, type(uint64).max);
        vm.roll(lockBlock);

        // actor locks in a guess whose hash is the answer for the next block
        // they can do this because the guess is just a value; correctness is determined at settle time
        bytes32 correctGuess;
        // We cannot know the next block hash before mining, but we can choose the guess as the answer
        // for the block right after lockInGuess. The blockhash of the lock block is known.
        // We set the actor's guess to the correct answer for the block immediately after lock.
        // The guess is keccak256(abi.encodePacked(blockhash(lockBlock + 1))) which is unknown at lock time;
        // instead we make the actor guess the answer for a block and then settle at that block.
        // The contract stores the block number as lockBlock + 1, so we mine to lockBlock + 1 and the
        // answer is keccak256(abi.encodePacked(blockhash(lockBlock + 1))).
        // We can compute blockhash(lockBlock + 1) only if it's in the past, so we do a two-step:
        // 1. lock the guess using the hash of the block that will be current when settling.
        //    We cannot compute a future blockhash, so we instead lock the guess as the hash of block 0,
        //    which is computed from the current blockhash when settling. To win, the actor needs to
        //    guess the hash of block lockBlock + 1. Since we control roll, we can set the guess after
        //    mining to lockBlock + 1? But lockInGuess must be called before that block.
        //
        // Simpler: we can set the guess to the answer for block (lockBlock + 1) by calling settle
        // after mining to lockBlock + 1. But the guess must be locked before. The answer for block
        // lockBlock + 1 is keccak256(abi.encodePacked(blockhash(lockBlock + 1))). At lock time we
        // cannot know it. However, we can pick the guess as the answer for a block that we mine
        // AFTER locking: we lock at block N, the contract records N+1. We then mine to N+1 and
        // the answer is keccak256(abi.encodePacked(blockhash(N+1))). We can compute the guess as
        // keccak256(abi.encodePacked(blockhash(N+1))) only after mining to N+1, but lockInGuess
        // can be called at N+1? No, lockInGuess must be before N+1 because the contract sets block
        // to block.number + 1 at lock time. If we lock at block N, block stored = N+1. We can
        // settle at block N+1 and the answer is blockhash(N+1). We cannot know blockhash(N+1)
        // before mining. But we can use a different approach: the actor can call lockInGuess with
        // a guess, then we mine to block N+1, then we call settle. To win, the guess must equal
        // keccak256(abi.encodePacked(blockhash(N+1))). We can set the guess after mining to N+1?
        // No, lockInGuess must be called before N+1 because it sets block = block.number + 1.
        //
        // Trick: call lockInGuess at block N with guess = keccak256(abi.encodePacked(blockhash(N)))
        // and then settle at block N+1? The answer is for block N+1, not N. So that fails.
        //
        // Alternate: We can use vm.roll to set the block number and then compute the blockhash
        // of the locked block. The contract uses blockhash(guesses[msg.sender].block) as the
        // preimage. So the guess must be keccak256(abi.encodePacked(blockhash(guesses[msg.sender].block))).
        // At lock time, guesses[msg.sender].block = block.number + 1. So the guess must be
        // keccak256(abi.encodePacked(blockhash(block.number + 1))). We cannot know that at lock time.
        //
        // Therefore, it is impossible to win unless we can predict a future blockhash. In a test
        // environment, we can control block numbers and hashes partially. Foundry's vm.roll sets
        // block.number. blockhash(x) for x in the past 256 blocks returns the hash. For a future
        // block, it returns 0. So if we lock at block N, guesses.block = N+1. We can mine to N+1
        // and then blockhash(N+1) is known. But the guess must be set before. To win, we can use
        // a different path: call lockInGuess with a guess that equals the answer for block 0?
        // No, blockhash for future blocks is 0. Then answer = keccak256(abi.encodePacked(bytes32(0))).
        // That is a constant! If the guessed block is in the future (or > 256 blocks ago), blockhash
        // returns 0. So we can set the guess to keccak256(abi.encodePacked(bytes32(0))) and then
        // force the block number such that blockhash(guesses.block) == 0. That happens if the
        // block number is > 256 blocks in the past, or in the future. But we can't set a future
        // blockhash. However, we can set the block number to a value where the locked block is
        // in the future relative to current block? The contract requires block.number > guesses.block
        // at settle. So guesses.block must be less than current block.number. So the locked block
        // is in the past relative to settle. To make blockhash return 0, the locked block must be
        // more than 256 blocks in the past. That's achievable: lock at block N, then mine to N+257,
        // then settle. But guesses.block = N+1, and blockhash(N+1) at block N+257 is 0 (since N+257 - (N+1) = 256, which is > 256? Actually blockhash returns 0 for blocks older than 256. 256 blocks ago is excluded. So if difference > 256, it's 0).
        // So we can force answer = keccak256(abi.encodePacked(bytes32(0))). Then the actor can
        // guess that constant and win! That is a general way to win.

        // So: guess = keccak256(abi.encodePacked(bytes32(0)))
        bytes32 zeroHash = keccak256(abi.encodePacked(bytes32(0)));

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(zeroHash);

        // Now mine far ahead so that blockhash(guesses.block) returns 0
        // guesses.block = lockBlock + 1. We need current block > lockBlock + 1 + 256
        vm.roll(lockBlock + 258);

        // settle
        vm.prank(actor);
        c.settle();

        // After a win, the reference pays 2 ether out; contract had 2 ether total (1 initial + 1 from actor)
        // so balance becomes 0. The bug pays only 1 ether, leaving 1 ether.
        assertTrue(address(c).balance == 0);
    }
}
